// src/components/common/TransactionForm.jsx
import React from 'react';
import './TransactionForm.css';

const TransactionForm = ({ 
  title, 
  isCare,       // if true, only show amount field
  txData, 
  onChange, 
  onSubmit, 
  onCancel,
  representative
}) => {
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    onChange({ target: { name, value } });
  };

  return (
    <div className="claim-card transaction-container">
      <div className="transaction-title">{title}</div>
      <div className="tx-form">
        {/* Only amount field for Customer Care */}
        <div className="field">
          <label>Transaction Amount *</label>
          <input
            type="text"
            name="amount"
            value={txData.amount}
            onChange={handleInputChange}
            placeholder="e.g., 150000"
            required
          />
        </div>
        
        <div className="field">
          <label>Transaction Date</label>
          <input
            type="text"
            name="date"
            value={txData.date}
            readOnly
            className="readonly"
          />
        </div>
        
        <div className="field">
          <label>Customer Care</label>
          <input
            type="text"
            value={representative || 'Shabani'}
            disabled
            className="readonly"
          />
        </div>
        
        <div className="form-actions">
          <button type="button" className="btn-outline" onClick={onCancel}>Cancel</button>
          <button 
            type="button" 
            className="submit-btn" 
            onClick={onSubmit}
            disabled={!txData.amount || parseFloat(txData.amount) <= 0}
          >
            <i className="fas fa-check"></i> Submit
          </button>
        </div>
      </div>
    </div>
  );
};

export default TransactionForm;
